(globalThis.TURBOPACK||(globalThis.TURBOPACK=[])).push(["object"==typeof document?document.currentScript:void 0,45519,(e,t,a)=>{t.exports=JSON.parse('[{"id":"fomo","name":"FOMO-only buys","tagline":"It can only be bought through the FOMO app.","blurb":"Every buy from the Meteora pool has to come through the FOMO app: the hook checks that FOMO\'s own signing wallet co-signed the transaction, and refuses the buy otherwise. Sells and wallet-to-wallet sends are never blocked, so holders can always exit. The dev wallet is also permanently whitelisted, so you can buy anywhere with it. Everyone else can only buy on FOMO. This lets the dev open up the pool on FOMO, which takes a few buys to trigger. When the curve graduates, Meteora switches the rule off and it trades anywhere.","family":"Guards","venue":"safe","program":"4Tabcoy1niosiNAGHMruLBFscgJWXZsVF3pfij3FqMB5","chips":["dev buy: 0.1 SOL"]},{"id":"pumpapp","name":"Pump App only","tagline":"It can only be bought in the Pump app.","blurb":"Every buy from the Meteora pool has to be made in the Pump app: the Pump app buys a token like this through Jupiter\'s app API and the OKX router, and the swap Jupiter builds for it carries a tag that jup.ag\'s own swaps don\'t. The hook only lets a buy through when it runs through that router and carries that tag. Buying on jup.ag, in FOMO, through trading terminals like Axiom and Photon, or straight from the pool is refused. Another app built on the same Jupiter API could also get through, which has been about 1 buy in 70 so far. Sells and wallet-to-wallet sends are never blocked, so holders can always exit. The dev wallet is permanently whitelisted, so you can buy anywhere with it. When the curve graduates, Meteora switches the rule off and it trades anywhere.","family":"Guards","venue":"safe","program":"BXax2KXrnT7qRf7cva9cLJpqDGXWywsw4ucLwtGiTa28","chips":["dev buy: 0.1 SOL"]},{"id":"social","name":"Social trading","tagline":"It only trades in FOMO or the Pump app: buys and sells.","blurb":"Every trade with the Meteora pool, buying and selling, has to be made in one of two apps. A FOMO trade is recognised by FOMO\'s own signature on the transaction, which nobody else can produce. A Pump app trade is recognised by the route it takes: the Pump app trades through Jupiter\'s app API and the OKX router, and the swap built for it carries a tag that jup.ag\'s own swaps don\'t. Trading on jup.ag, through terminals like Axiom and Photon, or straight with the pool is refused, in both directions. The Pump half isn\'t forgery-proof: another app built on the same Jupiter API could also get through. Because sells are restricted too, holders have no exit outside the two apps: if both ever stop trading the token, nobody can sell it. The rule only lifts if the curve graduates. Wallet-to-wallet sends always work. The dev wallet is permanently whitelisted, so you can buy and sell anywhere with it. When the curve graduates, Meteora switches the rule off and it trades anywhere.","family":"Guards","venue":"safe","program":"DMohCzuYMQUsmYAiitgtYtSpsBtyEw9UWZha7EGqTv8M","chips":["dev buy: 0.1 SOL"]},{"id":"wars","name":"Social Trading Wars","tagline":"FOMO against the Pump app. Every hour, the side with more holders takes the fees.","blurb":"A social-only coin with a war on. It only trades in FOMO or the Pump app, buys and sells, exactly like Social trading. Every wallet is on the side of the app it last bought through. Every hour the side with more holders wins that hour\'s war chest, about 1.6% of every trade, and it is split between everyone on the winning side by how much each holds, paid in SOL straight to their wallets. A tie rolls the chest into the next hour. These tokens trade with a 3% fee instead of 1%, and Hookvex\'s share is the same as on any token.","family":"Rewards","venue":"safe","program":"DMohCzuYMQUsmYAiitgtYtSpsBtyEw9UWZha7EGqTv8M","chips":["dev buy: 0.1 SOL","tokens a wallet must hold to count as a holder: 100000"]},{"id":"underwater","name":"Underwater","tagline":"The fees go to the holders who are down.","blurb":"A coin that pays the people it has hurt. Trades carry a 3% fee, and about 1.6% of every trade goes into a pot. Every five minutes the pot is shared between the holders who are underwater: whose tokens are worth less SOL at the pool\'s price than they paid for them. Each is paid in SOL by how much they are down, and never more than that. What a wallet is paid comes off its entry, so it is paid until it is back to even. The hook itself blocks nothing: it trades anywhere. A wallet\'s entry comes from its own buys from the pool; tokens sent to a wallet have no entry.","family":"Rewards","venue":"safe","program":"9eQyvzp3hfghBhA4VUECLZzyZswmFGcne1rfs9QN3CnL","chips":["tokens a wallet must hold to share in the pot: 10000"]},{"id":"quantum","name":"Quantum Jackpot","tagline":"Every round one holder wins the pot, drawn by quantum hardware.","blurb":"A jackpot that never stops. Trades carry a 3% fee, and about 1.6% of every trade goes into a pot. Every round (you choose 10 to 30 minutes) closes and one holder wins the whole pot, paid in SOL. The winner is drawn with a random number from the Australian National University\'s quantum random number generator, which measures quantum fluctuations in a vacuum. The number is published on-chain before the block that decides the draw exists, so nobody can pick the winner: not a validator, and not Hookvex. The more you hold, the better your odds, and only tokens you already held when the last round closed count, so buying in the final seconds wins nothing. The hook blocks nothing and it trades on any DEX.","family":"Rewards","venue":"safe","program":"9eQyvzp3hfghBhA4VUECLZzyZswmFGcne1rfs9QN3CnL","chips":["a winner is drawn every: 10","tokens a wallet must hold to enter: 10000"]},{"id":"opensea","name":"OpenSea only","tagline":"It only trades on OpenSea: buys and sells.","blurb":"Every trade with the Meteora pool, buying and selling, has to be made on OpenSea: every swap made on OpenSea carries OpenSea\'s own marker (a memo, sometimes also its wallet\'s signature), and the hook refuses any trade without it. Ordinary apps and bots don\'t add that marker, though anyone building their own transaction could. Because sells are restricted too, holders have no exit outside OpenSea. OpenSea hasn\'t yet been seen trading a token still on its bonding curve; if it can\'t, nobody but you can buy or sell until the curve graduates, and holders can only send it between wallets. Wallet-to-wallet sends always work. The dev wallet is permanently whitelisted, so you can buy and sell anywhere with it. When the curve graduates, Meteora switches the rule off and it trades anywhere.","family":"Guards","venue":"safe","program":"VqzxRoumJqbx99dQeWDoRC5XL48r5ZZYANwCgpuWVPW","chips":["dev buy: 0.1 SOL"]},{"id":"sellcaps","name":"Graduated sell caps","tagline":"The bigger your bag, the less you can sell in one go.","blurb":"Small holders sell freely, but the bigger a wallet\'s bag, the smaller its per-sell cap, down to a floor. A whale can build a position but can\'t dump it in one sell. The hook reads the bag straight from the sell, so there\'s nothing to fund and no minimum buy. Buys and wallet-to-wallet sends are never capped.","family":"Caps","venue":"safe","program":"9Am6KfHqhi3vYmZKpE2kRJxmbNvwggujNzqqSaqdor2Z","chips":["sell cap for small holders: 1 % supply","sell cap for the biggest bags: 0.1 % supply","bag size that gets the smallest cap: 3 % supply"]},{"id":"p2p","name":"P2P-only","tagline":"Moves wallet to wallet only until it graduates. Only you can buy the curve.","blurb":"Nobody can buy or sell it on a market: the hook refuses any transfer a program makes, so it only moves when a wallet sends it to another wallet. The one exception is your own wallet, which can buy from the bonding curve (all of it, if you like) and hand tokens out. When the curve fills up, the token graduates and Meteora switches the rule off, so from then on it trades normally everywhere.","family":"Guards","venue":"safe","program":"B9HAaxbFnz868uYsVPWBJr1hL2cfZvXqzhssR3V2VQaT","chips":[]},{"id":"maxhold","name":"Max per wallet","tagline":"No wallet can hold more than a set share of supply.","blurb":"After every buy or transfer the hook checks what the receiving wallet now holds, and refuses the trade if it would go over your cap, for example 1% of supply. The Meteora pool is exempt so trading and graduation work, and so is your own wallet. No per-wallet setup and nothing to fund.","family":"Caps","venue":"safe","program":"BVM8FK38fAJdWj4pezJh9xHaYaektV4f5Df9dq7y5TDC","chips":["max per wallet: 1 % supply"]},{"id":"hours","name":"Market hours","tagline":"Trades like a stock: Monday to Friday, 9:30am to 4pm New York time.","blurb":"The token only trades during the stock market\'s regular session: Monday to Friday, 9:30am to 4:00pm New York time, with daylight saving handled automatically. Outside those hours the hook refuses the trade. You choose whether sells stay open around the clock and whether stock-market holidays are observed. Sending between wallets always works, and your own wallet can always buy.","family":"Guards","venue":"safe","program":"EZet2oSoussVujse5U8W4T2NZsTuJ1rZBqQ8J188iJKk","chips":["after hours: closed","stock-market holidays: observe"]},{"id":"king","name":"King of the Hill","tagline":"The biggest buy takes the crown and earns from every trade.","blurb":"The largest qualifying buy holds the crown. To steal it, another wallet has to beat the King\'s winning buy, which slowly decays so the throne never becomes unreachable. While they hold the crown the King earns about 0.5% of every trade, paid in SOL by the program itself; selling or sending any tokens gives the crown up. The token page shows the King, the winning buy, the reign and a Hall of Kings. These tokens trade with a 1.65% fee instead of 1%, and they trade on any DEX. The game runs while the token is on its curve, so pick the Permanent curve to keep it going.","family":"Rewards","venue":"safe","program":"63VLLdKEZVjwKN4Y6CqeeFkLGzMoSZxFAXsfiLwnKKkD","chips":["smallest buy that can take the crown: 0.1 SOL","a challenger must beat the king by: 5 %","the bar to beat halves every: hour"]},{"id":"lockin","name":"Lock & earn","tagline":"Lock tokens without them leaving your wallet, and earn SOL from every trade.","blurb":"Holders lock tokens for a length of time and earn SOL from every trade while they\'re locked. Nothing is deposited: the tokens stay in the holder\'s own wallet, and the token itself refuses to sell or send them until the lock ends, so there is no staking contract holding anyone\'s coins. About 1% of every trade is paid in SOL to the wallets with locks, shared by how much each locked and for how long. Pick a ready-made setup (lock to earn, a long-term boost, loyalty tiers with bigger buys for lockers, one fixed lock for everyone) or set every number yourself, and lock your own launch buy so holders can see you can\'t sell. These tokens trade with a 2.25% fee instead of 1%, and they trade on any DEX. Locks and yield run while the token is on its curve, so pick the Permanent curve to keep them going.","family":"Rewards","venue":"safe","program":"CndZxZoVjv2RC9RX7DGfQzQru9a1kfAsEfUVVM37diGF","chips":["setup: earn","shortest lock: 7 days","longest lock: 90 days"]},{"id":"loans","name":"Loans, no liquidations","tagline":"Borrow SOL against tokens that never leave your wallet. Nothing is ever sold.","blurb":"Holders pledge tokens and borrow SOL against them. Nothing is deposited: the pledged tokens stay in the holder\'s own wallet, and the token itself refuses to sell or send them until they are released. The SOL comes from the token\'s own treasury, which fills with about 1% of every trade. There are no liquidations, no price that triggers anything and no deadline: a loan that isn\'t paid back simply keeps its tokens frozen, and the SOL it took came from trading fees, not from anyone\'s deposit. Loans are sized from the pool\'s book value (the SOL really in the pool shared over the tokens out of it), which is never above market value, so nobody can borrow back more than they paid in. Pair the token with a tokenized stock, a metal or another coin instead of SOL and everything works the same in that token: the treasury fills with it, and holders borrow it. Pick a ready-made setup or set every number yourself. These tokens trade with a 2.25% fee instead of 1% (3% when paired), and they trade on any DEX. Pledges and loans run while the token is on its curve, so pick the Permanent curve to keep them going.","family":"Rewards","venue":"safe","program":"6paHfhz6X3sh1XZS4uWVwJFEYFGuXJhrpEFs9VudbPRw","chips":["setup: standard","a pledge can borrow up to: 35 %","loan fee: 3 %"]},{"id":"arcade","name":"Arcade","tagline":"Beat the token\'s game to hold more than 0.1%.","blurb":"You upload a game. Anyone can hold up to 0.1% of the supply; a wallet that reaches the score you set in the game can hold any amount, for good. Playing is free. Each run is replayed on-chain with the game\'s own logic, so a score can\'t be faked, and a wallet\'s best score is kept forever. The game is sealed at launch and can never change. Sends are capped like buys, selling is never touched, your own wallet is exempt, and it trades on any DEX.","family":"Caps","venue":"safe","program":"9eQyvzp3hfghBhA4VUECLZzyZswmFGcne1rfs9QN3CnL","chips":[]},{"id":"iqtest","name":"IQ test","tagline":"Pass the token\'s IQ test to hold more than 0.1%.","blurb":"The token comes with a 20-question IQ test: number sequences, pattern grids and odd ones out, made fresh for every run. Anyone can hold up to 0.1% of the supply; a wallet that scores the IQ you set can hold any amount, for good. You pick the difficulty. A minute per question, the test can be taken again any time and the best score is kept. Every run is checked on-chain. Sends are capped like buys, selling is never touched, your own wallet is exempt, and it trades on any DEX.","family":"Caps","venue":"safe","program":"9eQyvzp3hfghBhA4VUECLZzyZswmFGcne1rfs9QN3CnL","chips":[]},{"id":"conviction","name":"Conviction cap","tagline":"Hold without selling and your own buy limit grows.","blurb":"The opposite of a flat whale cap. Every wallet starts with a small limit per buy; each minute, hour or day it holds without selling (you choose), its own limit climbs, up to a ceiling you set. Sell and that wallet\'s clock starts again. New money is throttled while proven holders earn the right to buy bigger. Sells are never capped, your own wallet is exempt, and it trades on any DEX.","family":"Caps","venue":"safe","program":"9eQyvzp3hfghBhA4VUECLZzyZswmFGcne1rfs9QN3CnL","chips":["starting buy cap: 0.1 % supply","cap grows every: day","growth each time: 0.1 % supply"]},{"id":"grudge","name":"The Grudge","tagline":"Dump your bag and the token remembers.","blurb":"Built for the wallets that farm a chart: buy, dump, buy back, dump again. The hook remembers every wallet that dumps, meaning it sells a share of its bag you choose (or more) within 24 hours. For a time you set after each dump, that wallet\'s buys carry a penalty: an extra tax paid in SOL, no buying at all, or a small limit on what it can hold. The grudge can grow with every repeat, and you can let a first dump or two pass. All of the tax goes to Hookvex\'s buyback and burn. Selling is never restricted, wallets that don\'t dump never notice it, and it trades on any DEX.","family":"Guards","venue":"safe","program":"9eQyvzp3hfghBhA4VUECLZzyZswmFGcne1rfs9QN3CnL","chips":["what counts as a dump: 50","the grudge lasts: 86400","repeat dumpers: grows"]},{"id":"redlight","name":"Red light, Green light","tagline":"Green: trading is open. Red: trading is paused. Nobody knows when it changes.","blurb":"Trading runs on a traffic light that changes at random. On green, anyone can buy and sell. On red, every buy and every sell is refused by the token itself, for everyone, until the light turns green again. Nobody knows when the next change is coming: not the traders, not you, not Hookvex. You choose how long a green and a red light last on average; each one is a roll of the dice, and a red light never lasts more than three times its average. The token\'s page shows the light and every change so far. Hookvex\'s keeper switches the light, by putting one rule on the token and taking it off again, and that is the only thing it can ever do to it. Sending tokens between wallets is never paused, and it trades on any DEX.","family":"Guards","venue":"safe","program":"9eQyvzp3hfghBhA4VUECLZzyZswmFGcne1rfs9QN3CnL","chips":["a green light lasts about: 5","a red light lasts about: 1"]},{"id":"options","name":"Options","tagline":"Holders sell the right to buy their tokens at a set price.","blurb":"Any holder can offer the right to buy some of their tokens at a price they choose, until a date they choose, for a payment up front. If the token goes above that price, the buyer takes the tokens for less than they are worth. If it doesn\'t, the holder keeps the tokens and the payment. While an offer is listed its tokens stay in the holder\'s wallet and the token itself won\'t let them leave, so an offer can always be filled. Once someone buys, those tokens are set aside for the buyer, who can take all or part of them any time before the offer ends. Buyers can take a whole offer or a piece of it. Everything is priced in SOL and settled between the two wallets; nothing goes through the pool. 5% of every payment buys back and burns HKVX. Trading is never restricted otherwise, and it works with any pair.","family":"Guards","venue":"safe","program":"9eQyvzp3hfghBhA4VUECLZzyZswmFGcne1rfs9QN3CnL","chips":["wallets that can have offers listed at once: 500"]},{"id":"polarity","name":"Polarity","tagline":"Two tokens, bull and bear, on one price. The winning side takes SOL from the other.","blurb":"You launch two tokens at once: a BULL and a BEAR, tied to one price you pick (SOL, Bitcoin, Ether, or any Hookvex token). Behind them is one pot of SOL, split between the two sides: you seed it at launch, and about 1.6% of every trade on either token is added to it. When the price goes up, SOL moves from the bear side to the bull side; when it goes down, the other way. The tokens do this themselves on every trade, with the leverage you choose, and neither side\'s share can ever run out. Any holder can redeem at any time: their tokens are burned and they are paid 98% of their share of their side\'s SOL. Anyone can add SOL to either side. Both trade on any DEX, on a permanent curve priced in SOL.","family":"Rewards","venue":"safe","program":"CoWTYzb2UynhtEX2vChAtHS7tDCRUegYcDFDx2Whmsvm","chips":["the price both tokens follow: SOL","leverage: 2","your seed: 0.5 SOL"]},{"id":"risingfloor","name":"Rising Floor","tagline":"A price under the token that only goes up. Redeem at it any time.","blurb":"Every trade pays about 1.6% into the token\'s own treasury, and the SOL in it is the floor: shared over every token that exists, it is a price any holder can always get. Redeem tokens at any time and they are burned; you are paid 98% of their floor value straight from the treasury, with no buyer needed and whatever the chart is doing. The other 2% stays behind, so every redemption lifts the floor for everyone still holding, and so does every trade. Nothing else can take SOL out of the treasury, not you and not Hookvex, so the floor can only rise. The token\'s own rules add to it: a wallet that dumps pays a share of its next buys into the floor, the first block can be kept for your launch buy alone, and you can cap what one wallet holds. It trades with a 3% fee on a permanent curve, priced in SOL.","family":"Rewards","venue":"safe","program":"9eQyvzp3hfghBhA4VUECLZzyZswmFGcne1rfs9QN3CnL","chips":["your launch buy: 0.1 SOL","dumpers pay the floor: 10","block zero protection: yes"]},{"id":"blockzero","name":"Block Zero Protection","tagline":"Only the dev buys in the first block, and that bag can\'t be sent anywhere.","blurb":"The first block of a launch is where bundles happen: the dev buys, and a string of side wallets buy in the same block before anyone else can. Here the first block belongs to your wallet alone. Your launch buy opens trading, and until that block is over every other buy is refused by the token itself, bundles included. From the next block on anyone can buy. Your wallet can never send its tokens to another wallet, so the launch bag can\'t be quietly spread across side wallets; everything you do with it is a sell that everyone can see. Selling is never restricted for anyone, and it trades on any DEX.","family":"Guards","venue":"safe","program":"9eQyvzp3hfghBhA4VUECLZzyZswmFGcne1rfs9QN3CnL","chips":["your launch buy: 0.1 SOL"]},{"id":"plague","name":"Plague","tagline":"You can only buy once someone has sent you some.","blurb":"Nobody can simply buy this token. A wallet can only buy if it already holds some, and the only way to get your first tokens is for someone who holds them to send you some. It starts with you: your launch buy makes your wallet patient zero, and you send tokens to the first wallets. Each of them can then buy, and can pass it on by sending tokens to anyone they like. A wallet stays infected for as long as it holds the token; sell or send away everything and it has to be sent some again before it can buy. Selling is never restricted, and it trades on any DEX.","family":"Guards","venue":"safe","program":"9eQyvzp3hfghBhA4VUECLZzyZswmFGcne1rfs9QN3CnL","chips":["your launch buy: 0.1 SOL","infection dose: 1 tokens"]},{"id":"custom","name":"Custom hook","tagline":"Describe the rule you want and AI writes the hook.","blurb":"Your own rules, written with AI. Say what you want the token to do, in your own words; the AI writes it as a short rule set, checks it with the real compiler and tests it, and you can edit every line. The rules can look at the trade, each wallet\'s own buys and sells, the clock in any time zone, the market cap, the transaction\'s fees and which app sent it. They are stored on-chain at launch, run on every transfer, can never change, and the token still trades on any DEX.","family":"Guards","venue":"safe","program":"9eQyvzp3hfghBhA4VUECLZzyZswmFGcne1rfs9QN3CnL","chips":[]},{"id":"editable","name":"Editable hook","tagline":"A Custom hook you can rewrite at any time, forever.","blurb":"A Custom hook whose rules are never locked. You launch with any rule set (or none) and can replace it whenever you like, as often as you like, with the same AI builder: only your wallet can make a change, and every change is made on-chain and shown on the token\'s page. 5% of the token\'s trading fees is set aside as its own fund that pays for the AI work on its rules; the other 80% still goes to the Hookvex buyback and burn. Holders should know the rules can change, including rules about selling. It still trades on any DEX, with the normal 1% fee.","family":"Guards","venue":"safe","program":"9eQyvzp3hfghBhA4VUECLZzyZswmFGcne1rfs9QN3CnL","chips":["who changes the rules: me","trading fee: 1.5 %","notice before a change takes effect: 0"]},{"id":"dao","name":"DAO hook","tagline":"Holders vote on the rules, and AI rewrites the hook.","blurb":"A Custom hook run by its holders. Anyone holding the minimum you set can sign in with their wallet, post an idea for the token\'s rules and vote ideas up or down. When an idea reaches the number of votes you set, the AI builder turns it into a rule set, checks and tests it, and Hookvex\'s keeper puts it on-chain. Nobody, including you, can change the rules any other way. 5% of the token\'s trading fees is set aside as its own fund that pays for the AI work and the changes; the other 80% still goes to the Hookvex buyback and burn. It still trades on any DEX, with the normal 1% fee.","family":"Guards","venue":"safe","program":"9eQyvzp3hfghBhA4VUECLZzyZswmFGcne1rfs9QN3CnL","chips":["tokens needed to take part: 1,000,000 tokens","votes for an idea to pass: 25 votes","notice before a change takes effect: 0"]},{"id":"hooki","name":"Hooki","tagline":"An AI agent that rewrites your token\'s hook whenever it wants.","blurb":"Hooki is an AI agent, and this token is his. He watches everything about it: buys, sells, volume, holders, market cap and how his own earlier changes worked out. Whenever he decides to, he rewrites the token\'s rules and Hookvex\'s keeper puts them on-chain. Nobody tells him what to do and nobody else can change the rules, including you. Every change, and his reason for it, is posted on the token\'s page. He will never lock holders in for good. 5% of the token\'s trading fees goes to his own wallet for this token, which pays for his thinking and his changes; anything it holds above 2 SOL he may spend, as he sees fit, on buying the token back and burning it; the other 80% still goes to the Hookvex buyback and burn. Normal 1% fee, and it trades on any DEX.","family":"Guards","venue":"safe","program":"9eQyvzp3hfghBhA4VUECLZzyZswmFGcne1rfs9QN3CnL","chips":["how often hooki looks at the token: 3600","notice before a change takes effect: 0"]},{"id":"schedule","name":"Trading hours","tagline":"Trades only on the days and hours you set, in any time zone.","blurb":"You set the trading week: which days the token trades and the hours on each day, in any time zone in the world, with daylight saving followed automatically. Outside those hours the hook refuses the trade. A day can run past midnight or stay open all day. You choose whether sells stay open around the clock. Sending between wallets always works, your own wallet can always buy, and the hours are fixed at launch.","family":"Guards","venue":"safe","program":"BUwCiwrRfVgNKEhHryBb626oKCRqNfm5hhkebrXKG6iY","chips":["outside your hours: closed"]},{"id":"skin","name":"Skin in the game","tagline":"Only wallets that still hold real SOL or USDC after buying can buy.","blurb":"Bot farms buy from wallets funded with dust. With this rule, a buy only goes through if the buyer still holds at least your minimum of SOL, or of USDC, after paying for it. You set both minimums, and either can be 0 to leave that currency out: for example 0 SOL and 500 USDC means only wallets holding 500 USDC can buy. Sells and wallet-to-wallet sends are never blocked, and your own wallet is exempt. The hook reads the buyer\'s own wallet and USDC balance, which trading apps like Jupiter and Axiom don\'t supply, so the token is bought and sold on its Hookvex page. A determined bot can still top a wallet up for the length of one transaction; this stops cheap dust-wallet farms.","family":"Guards","venue":"client","program":"2zSiLjfBo5t6arSCk5o9UyLGascwyLooGVhdLHcRBsje","chips":["minimum sol: 0.5 SOL","minimum usdc: 50 USDC"]},{"id":"pingpong","name":"Ping Pong","tagline":"Buys and sells take turns: one buy, then one sell, forever.","blurb":"Every trade with the pool has to answer the last one: after a buy the next trade must be a sell, and after a sell it must be a buy. Two buys or two sells in a row are refused, for everyone, the creator included. A trade smaller than your minimum still goes through when it\'s its turn, but doesn\'t hand the turn over, so dust can\'t play the game. Two trades of the token in one transaction are refused, so nobody can sneak a tiny opposite trade in with their real one. If nobody takes the turn for the time you set, either side can go next, so a quiet token never gets stuck. Wallet-to-wallet sends always work. The first trade must be a buy.","family":"Guards","venue":"safe","program":"Bf7ecqFieSoacTNbangY4trvnU7bVig6na1RMr6G84dk","chips":["minimum to take the turn: 0.01 % supply","turn frees up after: 10 minutes"]},{"id":"pegs","name":"Pegs","tagline":"Every whole unit you hold is a numbered object with its own art.","blurb":"The supply is split into a fixed collection of numbered objects, up to 65,535. Every whole unit a wallet holds is one of them, with its own number and its own art: buy across a whole unit and a new number is minted to you, sell below it and your newest one is burned back to the pool, and sending tokens to a friend moves your newest objects with them. Upload your own art at launch, one image per object or a smaller set shared across the numbers, or let Hookvex draw one from each number. Trading is never blocked by the objects: a wallet that bought elsewhere claims its objects on the token page. Buys and sells happen on the token\'s Hookvex page.","family":"Rewards","venue":"client","program":"2JwcGx9cUK1UyTsztkRAnCeAPgbJXkwCqSP9ghkPi3Md","chips":["objects in the collection: 10,000 objects"]},{"id":"potato","name":"Hot potato","tagline":"The latest buyer can\'t sell until someone buys after them.","blurb":"Whoever bought last is holding the hot potato: they can\'t sell or send the token until a different wallet buys after them, which passes the potato on. Everyone else trades and sends freely, and buys are never blocked. A buy has to be at least your minimum to pass the potato, so a dust buy from a friend\'s wallet can\'t free the holder. You can also let the potato go cold after a while, so a holder isn\'t stuck if trading goes quiet. Nobody is exempt, you included.","family":"Guards","venue":"safe","program":"CapP1YJk8Rh4d17szh45zXHy8vSMbZoNXfzm6zvNTgz7","chips":["minimum buy to pass the potato: 0.01 % supply","potato goes cold after: 0 minutes"]},{"id":"blocklist","name":"Blocklist","tagline":"Named wallets can never receive the token.","blurb":"The opposite of an allowlist: you name up to 200 wallets that can never receive the token. They can\'t buy it from the pool and nobody can send it to them; everyone else trades normally. The list is written on-chain at launch and sealed, so it can never change, and the token still trades on any DEX.","family":"Guards","venue":"safe","program":"8zw1psRFN541E1A3uzxB3uBXjUj3dVtkLHS3Ad99dFqP","chips":[]},{"id":"feecap","name":"Sniper-fee cap","tagline":"Buys paying sniper-sized priority fees or tips are refused at launch.","blurb":"Snipers win launches by outbidding everyone with huge priority fees and Jito tips. For a launch window you choose, the hook reads every buy\'s transaction and refuses it if it pays more than your cap in priority fee or in Jito tips. Normal buyers pay tiny fees, so they never notice. When the window ends, anyone can pay whatever they like. Sells are never blocked, and your own wallet is exempt.","family":"Guards","venue":"safe","program":"BPVEVJfsDvPQ4A8oRntVudUAJyaUvFuSJVk5tidKz7Fp","chips":["launch window: 10 minutes","max priority fee per buy: 0.002 SOL","max jito tip per buy: 0.002 SOL"]},{"id":"timecap","name":"Rising max per wallet","tagline":"Max per wallet starts small and rises on a timer.","blurb":"Every wallet\'s max holding starts small, for example 0.1% of supply, and rises for everyone on a timer: a fixed step or doubling, as often as you choose. It never stops rising, so the token opens up completely over time. Snipers can only grab a tiny bag at launch. The hook reads the receiving wallet\'s balance after every buy or transfer, so there\'s nothing to fund and no per-wallet setup. The Meteora pool and your own wallet are exempt.","family":"Caps","venue":"safe","program":"6AH1GVkqUdYCrbse28TcFSLyYTSiYqQVneaxvSBTSyp3","chips":["starting max per wallet: 0.1 % supply","how it rises: step","rises by: 0.1 % supply"]},{"id":"slidecap","name":"Sliding caps","tagline":"The max buy and max sell change as the market cap grows.","blurb":"You set the max per buy and max per sell at launch, then up to five market-cap levels where they change, for example max sell 1% at launch, 0.5% from $100,000 and 0.1% from $1,000,000. On every trade the hook reads the price from the token\'s own Meteora pool and applies the highest level the market cap has reached, so a whale has to exit in ever smaller pieces as the token grows. If the price falls back under a level, the level below applies again. Caps go as low as 0.001% of supply. Nobody is exempt, including you. Wallet-to-wallet sends are never capped.","family":"Caps","venue":"safe","program":"8uDCgT4KrMNsX6nJzqCFtLansP9AJef4deWWBk4nG9VA","chips":["max per buy at launch: 2 % supply","max per sell at launch: 1 % supply","then, as the market cap grows: 100000:1:0.5;500000:0.5:0.25;1000000:0.25:0.1"]},{"id":"capbeacon","name":"Beacon","tagline":"Trade it freely. When its market cap hits the target, its Entangled token unlocks.","blurb":"No cap and no gate. On every trade the Beacon\'s hook reads its own Meteora pool and remembers the highest market cap it has reached. Pair it with an Entangled token, and that token unlocks for good the first time the Beacon\'s market cap reaches the target you set.","family":"Reactive","venue":"safe","program":"8h3iUcxwcCb2YJW99HbTmPohhitPsE94dHDuEAhwBJ7U","chips":[]},{"id":"capentangled","name":"Entangled","tagline":"Locked until its Beacon token reaches a market cap you choose.","blurb":"Every transfer is refused until its Beacon token\'s market cap reaches your target, for example $20,000. The hook reads the Beacon\'s Meteora pool directly, and the first trade after the target is hit unlocks this token for good, even if the Beacon falls back later. The target is set in dollars and fixed in SOL at launch.","family":"Reactive","venue":"safe","program":"8h3iUcxwcCb2YJW99HbTmPohhitPsE94dHDuEAhwBJ7U","chips":["unlocks when the beacon\'s market cap reaches: 20,000 USD"]},{"id":"airdrop","name":"Buyer rewards","tagline":"Every buy earns the buyer tokens or NFTs from a vault you fill.","blurb":"Fill a vault with any token or with NFTs. Every qualifying buy records a reward for the buyer inside the transfer, and the buyer collects it on Hookvex: tokens, or one NFT per reward. It works for every buyer, even ones who have never held that token. Buys only earn while the vault can cover them, so every reward is covered. You can withdraw anything that isn\'t already owed to buyers, and anyone can top the vault up.","family":"Rewards","venue":"client","program":"3MNVGyhzq5iLN2ZAnkSnBdwqEomtdQ9vt7qS6nheauok","chips":["minimum buy to earn: 0.05 % supply","reward-record rent pool: 0.05 SOL"]},{"id":"breathing","name":"Breathing cap","tagline":"The buy cap rises and falls on the clock, forever.","blurb":"An oscillator inside the hook swings the per-buy cap up and down on a fixed cycle: wide open at the peaks, tight at the troughs, then open again, for the life of the token with nothing to crank. You choose the cycle length, the base cap and how far it swings. Sells and wallet-to-wallet sends are never capped, and your own wallet can buy any size.","family":"Dynamics","venue":"safe","program":"C7Whr2PbMHGAt8J7gpvRVfmUqhW9nBk17qBbZDmdnFmk","chips":["cycle length: 300 seconds","base cap: 1 % supply","swing: 60 % of the base"]},{"id":"momentum","name":"Momentum","tagline":"Buying revs it up; a quiet market lets it ring down.","blurb":"A damped oscillator that starts at rest. Every buy kicks it, in proportion to its size, and the cap swings up with it, so a run of buying opens the door to bigger buys. Then it swings back below the base before settling, and damping bleeds the energy off when trading stalls. Sells and wallet-to-wallet sends are never capped, and your own wallet can buy any size.","family":"Dynamics","venue":"safe","program":"C7Whr2PbMHGAt8J7gpvRVfmUqhW9nBk17qBbZDmdnFmk","chips":["natural period: 120 seconds","damping: 8 % per second","buy energy: 40 %"]},{"id":"resonance","name":"Resonance","tagline":"Buy in rhythm and the cap swings wide open.","blurb":"Momentum tuned for rhythm: a lightly damped oscillator with a natural period you choose. Buys that land in step with it (one every period) pile energy on and swing the cap far wider than the same buys landing at random; on devnet, four buys in rhythm built five times the energy of four off rhythm. A community that buys together, on the beat, unlocks the biggest buys. Sells and wallet-to-wallet sends are never capped, and your own wallet can buy any size.","family":"Dynamics","venue":"safe","program":"C7Whr2PbMHGAt8J7gpvRVfmUqhW9nBk17qBbZDmdnFmk","chips":["the beat: 60 seconds","damping: 2 % per second","buy energy: 40 %"]},{"id":"coupled","name":"Coupled resonator","tagline":"Two oscillators inside one token, trading energy in beats.","blurb":"Two coupled oscillators in the hook. Buys energise the first, which sets the cap; the coupling then pours that energy into the second and back again, so the cap swells, fades as the energy moves away, and swells again: it literally beats. Sells and wallet-to-wallet sends are never capped, and your own wallet can buy any size.","family":"Dynamics","venue":"safe","program":"C7Whr2PbMHGAt8J7gpvRVfmUqhW9nBk17qBbZDmdnFmk","chips":["natural period: 180 seconds","coupling: 20 %","damping: 2 % per second"]},{"id":"reactive","name":"Reactive pair","tagline":"Its per-buy cap moves with a partner token\'s buying and selling.","blurb":"The per-buy cap loosens as a partner token is accumulated and tightens as it\'s dumped: cap = base + sensitivity × partner net pressure. A continuous on-chain reaction to another market, enforced inside the swap.","family":"Reactive","venue":"verified","program":"BCiJ49rbFS7Lw6QfbxweBQ5a4RVsif12kHBnx4QHBUxM","chips":["base cap: 1 % supply per buy","sensitivity: 25 %"]},{"id":"entangled","name":"Entangled (volume)","tagline":"Locked until enough of its Beacon token has changed hands.","blurb":"Transfers stay frozen until a set amount of a partner Beacon token has changed hands. Buys, sells and wallet transfers of the Beacon all count. Then it unlocks automatically, for good. Launch the two as a pair and trading the Beacon opens this one.","family":"Reactive","venue":"verified","program":"5aAXdggDpJBtAfDoFusTp44tj5XpBXbxuCwDqpc17SBb","chips":["unlocks after this share of the beacon changes hands: 5 % of its supply"]},{"id":"index","name":"Weighted index","tagline":"Track a weighted basket of other Hookvex tokens.","blurb":"The cap moves with the weighted sum of a basket\'s net buy pressure — a sector index as a token, with the heavy members moving it hardest. Members must be Hookvex reactive-family tokens.","family":"Reactive","venue":"verified","program":"GnxyEq4SFFBXLN3ejVmNSFnciDB3ssApXRQs1eTnz2XT","chips":["base cap: 1 % supply / buy","sensitivity: 25 %"]},{"id":"inverse","name":"Inverse pair","tagline":"Chokes as its rival pumps — anti-correlated rotation.","blurb":"The mirror of the reactive pair: the cap tightens as a rival token runs hot and relaxes as it cools, down to a floor. Two inverse-coupled tokens naturally rotate capital between themselves.","family":"Reactive","venue":"verified","program":"ATtqAHQiSNx3X1U316uW3aUm6hKvJQtEXdQvrZfCZouH","chips":["cap when rival is cool: 2 % supply / buy","sensitivity: 25 %","cap when rival is hot: 0.1 % supply"]},{"id":"guard","name":"Trade guard","tagline":"No single trade can move more than a set share of supply.","blurb":"Every buy, sell and transfer is capped at the same share of supply, for example 0.5%. Anything bigger is refused inside the swap, so no whale can grab or dump a big bag in one trade.","family":"Guards","venue":"verified","program":"9Kvwjjf2f9jP64JuC5AHfCQdxynHV1e678kfZCpiJ31z","chips":["max per trade: 0.5 % supply"]},{"id":"halving","name":"Halving mining","tagline":"Every buy mines a reward token — on a halving schedule.","blurb":"On launch, Hookvex mints a brand-new reward token and creates a vault for it that only your token\'s hook can mint into. Every trade mints the reward to that vault — and the amount halves each period, decaying Bitcoin-style. Holders stake the coin on the token\'s page to claim their pro-rata share of the vault; the amount is derived from your mint, not a destination you pick. Fully on-chain, mint-keyed, Meteora-safe.","family":"Emission","venue":"verified","program":"H8ceAVapJUohrhs2pdy39LY3xqgKsR9B5s2FWT2t2tjo","chips":["reward per trade (at launch): 100 reward tokens","reward halves every: 24 hours"]},{"id":"dumpcatcher","name":"Dump-catcher","tagline":"Every sell burns a slice of the reward token.","blurb":"On each sell (tokens flowing back to the pool), the hook burns a percentage of the reward-token vault in-flight — a fully on-chain deflationary response to dumping, no crank, no keeper.","family":"Emission","venue":"safe","program":"H8ceAVapJUohrhs2pdy39LY3xqgKsR9B5s2FWT2t2tjo","chips":["burn on sell: 1 % of each sell"]},{"id":"jackpot","name":"Jackpot","tagline":"A 1-in-N trade mints a big reward payout — you set the odds and the size.","blurb":"On-chain randomness (SlotHashes) rolls on every trade: one in every N trades mints your chosen multiple of the base reward to the token\'s reward vault, the rest mint 1×. You set both the odds (1 in N) and the payout (×). Holders stake the coin to claim their pro-rata share of the vault — a trustless lottery driven by trading itself.","family":"Emission","venue":"safe","program":"H8ceAVapJUohrhs2pdy39LY3xqgKsR9B5s2FWT2t2tjo","chips":["base reward per trade: 50 reward tokens","jackpot odds (1 in n): 10 trades","jackpot payout: 10 × the base reward"]},{"id":"buyburn","name":"Buyback & burn","tagline":"Trading fills a reward vault; a public burn keeps it scarce.","blurb":"Every trade mints a reward token to a per-mint vault. Anyone can trigger a permissionless burn that torches everything above a floor — a credible, on-chain buy-and-burn enforced by the chain, not a team\'s promise.","family":"Rewards","venue":"verified","program":"FiKwxPjoNPx1W4YiBTAtgjvuWnyDpy8A3SFkA2aPiL1U","chips":["reward per trade: 100 reward tokens","keep floor: 0 reward tokens"]},{"id":"chapters","name":"Chapters","tagline":"A max per wallet that doubles every time enough volume trades.","blurb":"Each wallet can hold at most the current cap. The cap starts small and doubles every time the total volume traded crosses another chapter, for example every 10,000,000 tokens. Early buyers get a fair, small allowance; the token opens up as it earns real volume. Selling back into the pool always works.","family":"Caps","venue":"verified","program":"A7m1Pw8Kj8YfSEjZe3SEHAzeFE3xZPTmH4XqhLqRhQsc","chips":["starting max per wallet: 1 % supply","volume per chapter: 10,000,000 tokens traded"]},{"id":"vise","name":"The Vise","tagline":"The cap tightens over time toward a floor.","blurb":"The max trade size shrinks by 1 basis point every N seconds, ratcheting down toward a floor — a clock-driven squeeze that steadily reduces how much any single trade can move, purely on-chain.","family":"Caps","venue":"verified","program":"A7m1Pw8Kj8YfSEjZe3SEHAzeFE3xZPTmH4XqhLqRhQsc","chips":["starting cap: 2 % supply","cap shrinks by 0.01% of supply every: 300 seconds"]},{"id":"antisniper","name":"Anti-bundle","tagline":"Only a few trades per block, so bundlers can\'t sweep the launch.","blurb":"The hook counts trades in each Solana block and refuses any past your limit. A bundler packing many buys into one block gets the first few at most, so nobody can buy up the launch in a single shot.","family":"Guards","venue":"safe","program":"AsqN4BA2cGmzbajL5rdg8rmfAsWs2K4TBS7Eqa8eLaY8","chips":["max trades per block: 3 trades"]},{"id":"oraclefloor","name":"Price floor","tagline":"Halt trading when SOL/USD falls below your floor.","blurb":"Reads a live Pyth SOL/USD price — bridged on-chain by Hookvex\'s keeper — and rejects every transfer while the price sits under your floor. A hard, market-conditional guard enforced in the swap itself.","family":"Guards","venue":"safe","program":"Gi1RsSKvyKvGWcFC3ytboMwvgrbq57LQZcxvx9Y6WY1L","chips":["sol/usd floor: 50 $"]},{"id":"dividends","name":"SOL dividends","tagline":"Every buy pays a SOL dividend to the buyer — claimable, real yield.","blurb":"You pre-fund a SOL pool at launch. On every buy, the hook opens the buyer\'s claim slot (inside the swap, no pre-registration) and drips a fixed SOL dividend into it from the pool. Holders claim their accrued SOL any time. Real, on-chain yield paid in SOL — not a minted token — funded by you and enforced by the swap. Because the slot is keyed on the buyer, trading goes through Hookvex\'s swap route. Proven live on Meteora.","family":"Rewards","venue":"client","program":"3MYbfUJVKsKnyYJ2QSXdgchoeW8hc7fqMBBuc51pDHuo","chips":["dividend per buy: 0.002 SOL","dividend pool: 1 SOL","minimum qualifying buy: 0.05 % supply"]},{"id":"tokendividends","name":"Token dividends","tagline":"Every buy pays the buyer your reward token — claimable, per holder.","blurb":"Like SOL dividends, but paid in a brand-new reward token you name at launch. Every buy accrues a fixed amount of the reward token to the buyer\'s slot (created inside the swap, no pre-registration); holders mint what they\'re owed any time. The reward is a separate classic-SPL token minted by your token\'s hook — the coin itself is never touched. Per-buyer, on-chain, funded by emission rather than a pool. Traded through Hookvex\'s swap route.","family":"Rewards","venue":"client","program":"3MYbfUJVKsKnyYJ2QSXdgchoeW8hc7fqMBBuc51pDHuo","chips":["reward per buy: 1,000 reward tokens","slot-rent pool: 0.5 SOL","minimum qualifying buy: 0.05 % supply"]},{"id":"vesting","name":"Holder vesting","tagline":"Each wallet unlocks its bag on its own clock — anti-dump by construction.","blurb":"Every wallet\'s tokens unlock on a schedule that starts the moment it first buys: nothing during the cliff, then a fixed percentage every period you choose, from hourly to weekly. A wallet can only sell what it has unlocked — the hook vetoes any sell beyond its own vested share, per holder, enforced in the swap. No team multisig, no snapshot: the lock lives in the token. Traded through Hookvex\'s swap route. Proven live on Meteora.","family":"Caps","venue":"client","program":"3MYbfUJVKsKnyYJ2QSXdgchoeW8hc7fqMBBuc51pDHuo","chips":["only vest early buyers: 0 hours","cliff: 24 hours","unlock each period: 10 %"]},{"id":"realyield","name":"Dividends","tagline":"Every buy pays the buyer a token you choose, straight to their wallet.","blurb":"Pick any standard SPL token you hold (USDC, a memecoin, a whole-number collectible token) and fund a vault with it at launch. On every buy, the hook sends a fixed amount from the vault to the buyer\'s wallet, where it just shows up, with nothing to claim. The limits: the buyer must already hold that token (a wallet without it is skipped, the buy still goes through), the vault is finite, and it pays one token, so a vault of different NFTs can\'t be handed out one per buy. Anyone can top the vault up. Trades through the Hookvex route.","family":"Rewards","venue":"client","program":"6nxb6Q2v3LYLqwyxeCXL9aQd58omqRZ4sTHjswC4SV3L","chips":["reward token decimals: 6 decimals","reward per buy: 1 reward tokens","treasury funding: 1,000 reward tokens"]},{"id":"tieredmembership","name":"Tiered membership","tagline":"Hold more of the members\' token, buy more at once.","blurb":"A membership ladder instead of a turnstile. Wallets still need your gate token to receive this one, but now the amount they hold sets how much they can buy in a single trade: a small holding gets a small limit, the top threshold lifts the limit entirely. One token, three rungs, checked inside every trade. The limit is per trade — this hook keeps no running per-wallet total, so it doesn\'t pretend to enforce one. Traded through Hookvex\'s route.","family":"Guards","venue":"client","program":"5M6KxRdyf3Vkw27prDB3KHF4A2xGPvTmjA2DK3abLo4r","chips":["dues per trade: 0.0005 SOL","bronze: hold at least: 1,000 membership tokens","bronze buy limit: 0.05 % supply"]},{"id":"holdercap","name":"Growing holder cap","tagline":"Only N wallets can hold it — and N grows on a clock.","blurb":"The token opens with a fixed number of seats and widens on a schedule you set: so many wallets at launch, a few more every period, up to a ceiling. A wallet takes a seat the moment its balance goes from zero to non-zero, so buying more once you\'re in is never gated — and a wallet that sells out completely gives its seat straight back to whoever\'s next. The cap is on wallets, not on people: every extra wallet costs slot rent and a real minimum buy, which is friction, not a guarantee. And it limits how many hold, not how much any one of them holds. Traded through Hookvex\'s route.","family":"Caps","venue":"client","program":"B2YVN1bWc95pSDBcZTpKgaH3v2JbmNKWRE5rSYNQ1m2x","chips":["seats at launch: 25 wallets","seats added each period: 10 wallets","how often seats open: 6 hours"]},{"id":"milestonetreasury","name":"Milestone treasury","tagline":"Locked money that only unlocks as the holder base grows.","blurb":"\\"We\'ll donate as we grow\\" turned into something the chain does on its own. You lock SOL at launch and set holder-count milestones; each crossing frees one tranche to a beneficiary address fixed at launch. The hook counts distinct holders rather than volume on purpose — one wallet can wash-trade volume in a loop, but every new holder costs a real minimum buy and its own slot rent. Releases are permissionless: you can\'t withhold a tranche and you can\'t pull one forward.","family":"Rewards","venue":"client","program":"B2YVN1bWc95pSDBcZTpKgaH3v2JbmNKWRE5rSYNQ1m2x","chips":["treasury to lock: 1 SOL","milestone 1: 10 holders","milestone 2: 50 holders"]},{"id":"abandonmentrefund","name":"Abandonment refund","tagline":"If the token goes quiet, the treasury goes back to holders.","blurb":"An honest dead-man\'s switch. You lock SOL at launch; every trade resets a clock. If the token goes untraded for the window you set, anyone can open the treasury — it snapshots and becomes claimable pro-rata by whoever still holds, in proportion to what they hold. If the team walks away, the money comes back, and nobody has to be trusted to trigger it. \\"Abandoned\\" is only ever a proxy: one wash trade inside the window keeps the clock alive forever, so pick a window with that in mind.","family":"Rewards","venue":"client","program":"B2YVN1bWc95pSDBcZTpKgaH3v2JbmNKWRE5rSYNQ1m2x","chips":["treasury to lock: 1 SOL","untraded before refund: 30 days","slot rent pool: 0.3 SOL"]},{"id":"referral","name":"Referral rewards","tagline":"Every buy pays the buyer — and whoever referred them.","blurb":"A referral tree welded to the coin. Share your link; when someone buys through it, the SOL dividend that buy earns is split between them and you, at a share you set. The link is bound on-chain the first time they buy and can never be rewritten or switched off, so referrers can\'t be stiffed later. Referring yourself is rejected. Traded through Hookvex\'s route, which binds the referrer in the same signature as the buy.","family":"Rewards","venue":"client","program":"3MYbfUJVKsKnyYJ2QSXdgchoeW8hc7fqMBBuc51pDHuo","chips":["dividend per buy: 0.002 SOL","referrer\'s share: 30 %","dividend pool: 1 SOL"]},{"id":"twoclass","name":"Presale + public launch","tagline":"Early buyers get in first but vest; everyone after is liquid.","blurb":"The structure real launches use, enforced by the chain instead of a spreadsheet. Wallets that buy during the presale window have their tokens vest on a cliff-and-drip schedule — they got in early, so they\'re locked in. Everyone who arrives after the window buys freely with no lock at all. Which class you\'re in is decided by the block you first bought, on-chain, and can\'t be edited afterwards.","family":"Caps","venue":"client","program":"3MYbfUJVKsKnyYJ2QSXdgchoeW8hc7fqMBBuc51pDHuo","chips":["presale window: 24 hours","presale cliff: 24 hours","presale unlock each period: 10 %"]},{"id":"convictioncap","name":"Conviction cap","tagline":"Hold without selling and your own buy limit grows.","blurb":"The opposite of a flat whale cap. Every wallet starts with a small per-trade limit; the longer it holds without selling, the higher its own limit climbs, up to a ceiling you set. Sell and the clock resets to the start. New money is throttled while proven holders earn the right to size up — a fair launch that opens per person rather than all at once. Pair it with a max-per-wallet if you\'re worried about someone farming it across many wallets.","family":"Caps","venue":"client","program":"3MYbfUJVKsKnyYJ2QSXdgchoeW8hc7fqMBBuc51pDHuo","chips":["starting buy cap: 0.1 % supply","cap growth per day held: 0.1 % supply","cap ceiling: 2 % supply"]},{"id":"diamondhand","name":"Diamond-hand dividend","tagline":"Hold longer, earn bigger SOL dividends — selling resets your streak.","blurb":"A SOL dividend paid on every buy, scaled by how long you\'ve held: the longer since your last sell, the bigger each buy\'s payout, up to a cap. Any sell resets your streak to zero, so the reward flows to patient holders and dumpers fall back to the base rate. Funded by a SOL pool you pre-fund; claim your accrued SOL any time. Traded through Hookvex\'s swap route.","family":"Rewards","venue":"client","program":"3MYbfUJVKsKnyYJ2QSXdgchoeW8hc7fqMBBuc51pDHuo","chips":["base dividend: 0.002 SOL","bonus per day held: 25 % per day","max bonus: 300 %"]},{"id":"whalegraduated","name":"Graduated sell caps (slots)","tagline":"The bigger your bag, the less you can sell in one trade.","blurb":"A progressive anti-dump: small holders trade freely, but the more a wallet has accumulated, the tighter its per-sell cap — down to a floor. Whales can build a position but can\'t unload it in one go, enforced per wallet in the swap. Traded through Hookvex\'s swap route.","family":"Caps","venue":"client","program":"3MYbfUJVKsKnyYJ2QSXdgchoeW8hc7fqMBBuc51pDHuo","chips":["base sell cap: 1 % supply","floor sell cap: 0.1 % supply","reaches floor at holding: 3 % supply"]},{"id":"dues","name":"Membership dues","tagline":"Hold a membership token AND pay dues to receive it.","blurb":"A members-only token with a turnstile: to buy or receive it, a wallet must already hold a gate token you choose (a membership NFT, another coin) AND pay a dues fee in the same transaction. Both checks run in the swap — no separate gate contract. Members can sell back to the pool freely. Traded through Hookvex\'s swap route.","family":"Guards","venue":"client","program":"5M6KxRdyf3Vkw27prDB3KHF4A2xGPvTmjA2DK3abLo4r","chips":["dues per trade: 0.005 SOL"]},{"id":"maxwallet","name":"Max per wallet (lifetime)","tagline":"A hard cap on how much any single wallet can ever buy.","blurb":"The hook keeps a per-wallet tally of everything a wallet has received and rejects the trade that would push it over your cap — a true fair-launch max-per-wallet, enforced in the swap, not a snapshot. The wallet\'s slot is created on its first buy (no pre-registration). Enforced on-chain; because the slot is keyed on the buyer, trading needs a Hookvex-aware client.","family":"Caps","venue":"client","program":"GaFtqyc9vCurVxPtQHKSyg66KeVp7rBwQL6Mkwj9U51y","chips":["max per wallet: 1 % supply","wallet slots to fund: 200 wallets","minimum first buy: 0.01 % supply"]},{"id":"cooldown","name":"Wallet cooldown","tagline":"Each wallet must wait between buys — per-wallet anti-spam.","blurb":"Every wallet gets its own cooldown: after receiving, it can\'t receive again until N blocks have passed. Independent per wallet, so one buyer\'s cooldown never blocks another — an on-chain anti-bot / anti-spam throttle. Slots are created lazily on first buy. Because the slot is keyed on the buyer, trading needs a Hookvex-aware client.","family":"Guards","venue":"client","program":"GaFtqyc9vCurVxPtQHKSyg66KeVp7rBwQL6Mkwj9U51y","chips":["cooldown: 25 blocks","wallet slots to fund: 200 wallets","minimum first buy: 0.01 % supply"]},{"id":"antidump","name":"Anti-dump caps","tagline":"A loose cap on buys and a tight cap on sells — enforced in the swap.","blurb":"The hook tells a buy from a sell by looking at who\'s sending: a swap out of the pool is a buy, a swap into the pool is a sell. It applies a separate size cap to each side, so you can let people buy freely while capping how much any single trade can sell — an on-chain anti-dump that a whale can\'t route around. Mint-keyed, confirmed live on Meteora (a 90%-of-bag sell is rejected while buys and small sells pass).","family":"Caps","venue":"verified","program":"Ft8R4BsJp7n3dGKsd1RbAi3WrvkiH5s5z2jyDztEQJ6f","chips":["max per buy: 2 % supply","max per sell: 0.25 % supply"]},{"id":"dexonly","name":"DEX-only","tagline":"Moves only through a DEX, never wallet to wallet.","blurb":"The hook reads its own CPI stack depth: a plain wallet-to-wallet transfer runs it at depth 2, a DEX/router swap one frame deeper. This mode rejects the direct transfers, so the token can only move through an exchange — no quiet OTC / off-book wallet moves. Mint-keyed, confirmed live on Meteora.","family":"Guards","venue":"verified","program":"4FYZUzNqHxLRLs8bhoQf71yRW8i2jPxJxLZJFcqB9Xom","chips":[]},{"id":"p2ponly","name":"P2P-only (no curve)","tagline":"Blocks DEX swaps — the token only moves wallet-to-wallet.","blurb":"The inverse of DEX-only: the hook rejects any transfer nested under a program (a DEX/router swap runs it one frame deeper than a direct transfer), so the token can\'t be bought or sold on an AMM — it only moves directly between wallets. A deliberate non-tradeable / airdrop-locked / OTC-only token. Mint-keyed, confirmed live on Meteora.","family":"Guards","venue":"verified","program":"4FYZUzNqHxLRLs8bhoQf71yRW8i2jPxJxLZJFcqB9Xom","chips":[]},{"id":"venuelock","name":"Venue-locked","tagline":"Trades only through its Meteora pool, never wallet to wallet.","blurb":"The hook checks that the transaction routes through the Meteora pool program; a plain wallet-to-wallet transfer (which doesn\'t) is rejected. Every trade hits your official liquidity, and the token can\'t be quietly moved OTC or between insider wallets. Mint-keyed, Meteora-verified — normal buys and sells just work.","family":"Guards","venue":"verified","program":"3uxoNzXjn6hKxuFqi5sZjnSoFauSXjnq6i9vWPJf99Zs","chips":[]},{"id":"royalty","name":"Enforced royalty","tagline":"Every trade pays you a royalty — on-chain, unavoidable.","blurb":"The hook rejects any transfer whose transaction doesn\'t also pay your royalty to your wallet, verified from the transaction itself — the WEN-royalty idea, actually enforced in the transfer path with no marketplace cooperation. Because the payment must ride in the swap, this token trades through the Hookvex route (a bare aggregator swap won\'t include it) — best for collectibles and low-velocity tokens.","family":"Guards","venue":"client","program":"3uxoNzXjn6hKxuFqi5sZjnSoFauSXjnq6i9vWPJf99Zs","chips":["royalty per trade: 0.005 SOL"]},{"id":"tithe","name":"Tithe token","tagline":"Every trade donates to a cause you choose — by construction.","blurb":"Same enforcement as the royalty, but the payment goes to an address you name — a charity, a treasury, a public-goods fund. Every trade of the token funds the cause, verified in the transaction and rejected if it\'s missing. Trades through the Hookvex route (the donation must ride in the swap tx).","family":"Guards","venue":"client","program":"3uxoNzXjn6hKxuFqi5sZjnSoFauSXjnq6i9vWPJf99Zs","chips":["donation per trade: 0.005 SOL"]},{"id":"allowlist","name":"Allowlist token","tagline":"Only wallets on your list can buy and hold it.","blurb":"You provide a list of wallet addresses at launch; the hook only lets those wallets receive the token, verified against a Merkle root with a proof carried in the trade. A presale/whitelist or members-only token with no separate presale contract — the allowlist lives in the token. Anyone on the list can sell back to the pool; non-listed wallets can\'t buy. Trades through the Hookvex route (it attaches the proof).","family":"Guards","venue":"client","program":"3uxoNzXjn6hKxuFqi5sZjnSoFauSXjnq6i9vWPJf99Zs","chips":[]},{"id":"rollingwaitlist","name":"Rolling waitlist","tagline":"Add wallets in waves — access widens on your schedule.","blurb":"An allowlist you can widen after launch. Start with wave one, then publish new waves as more people sign up — each wave replaces the on-chain list. Be honest with your community about the trade: until you freeze it, the same power that adds wallets can remove them, so every change is versioned on-chain and the token page shows the current wave. Freezing is one click and permanent.","family":"Guards","venue":"client","program":"3uxoNzXjn6hKxuFqi5sZjnSoFauSXjnq6i9vWPJf99Zs","chips":[]},{"id":"progressivetax","name":"Exit toll","tagline":"Selling costs a fee that scales with how much you sell.","blurb":"Every sell must pay a fee in the same transaction, and the fee scales with the number of tokens sold — small exits cost little, big ones cost real money. Buying is free. The fee goes to an address you name (a treasury, a charity, yourself) and the sell is simply rejected if it isn\'t paid, so it funds something and dampens dumping at once. Note it\'s priced per token, not as a percentage of value: a hook can see how many tokens move but never what they\'re worth.","family":"Guards","venue":"client","program":"3uxoNzXjn6hKxuFqi5sZjnSoFauSXjnq6i9vWPJf99Zs","chips":["toll per 1,000 tokens sold: 0.0005 SOL"]},{"id":"gatedlaunch","name":"Gated launch","tagline":"Your list buys first — then it opens to everyone when it graduates.","blurb":"The same Merkle allowlist, but launched on a graduating curve on purpose. While the token is on the bonding curve only wallets on your list can buy. When it fills the curve and graduates to a full AMM, the migration takes the transfer hook off — so the gate disappears by itself and the token becomes permissionlessly tradeable by anyone, forever. Your people first, then the world, with both halves enforced by the chain rather than promised.","family":"Guards","venue":"client","program":"3uxoNzXjn6hKxuFqi5sZjnSoFauSXjnq6i9vWPJf99Zs","chips":[]},{"id":"marketmon","name":"Market monitor","tagline":"Throttles buys per block and publishes a live buy/sell feed.","blurb":"A composite market hook: it tells buys from sells by provenance, caps how many buys clear per block (anti-bundler), and keeps running buy/sell counts and volumes in on-chain state — so the token doubles as its own live market feed any program can read. Confirmed live on Meteora.","family":"Guards","venue":"verified","program":"DURKELkRRfrCuLs4fgSmDFPX2bXDCXDEQhQU2925JkNb","chips":["max buys per block: 3 buys"]},{"id":"basket","name":"Basket index","tagline":"Track an equal-weight basket of other Hookvex tokens.","blurb":"Like the weighted index, but every member counts equally: the cap moves with the average net buy pressure of a basket of reactive-family tokens. A sector or theme token that reacts to a whole group at once. A separate program from the weighted index.","family":"Reactive","venue":"safe","program":"BfTwawNVYa1V1D3naJPrb9zmpv2ypXri99n224ec2SiB","chips":["base cap: 1 % supply / buy","sensitivity: 25 %"]},{"id":"holdergated","name":"Holder-gated","tagline":"Only wallets holding your chosen token can receive.","blurb":"To receive this token a wallet must already hold a gate token you pick — a membership token, an NFT, another coin. The hook reads the recipient\'s balance of the gate mint and rejects the transfer if it\'s missing or empty: community-gated / allowlist-by-holding / soulbound-to-a-group, with no maintained address list. Because the check is keyed on the recipient, trading needs a Hookvex-aware client.","family":"Guards","venue":"client","program":"2WsdXUpABzpXbiPcKrDYypdgzr2EybGorWFHBDXYtSGx","chips":[]},{"id":"beacon","name":"Beacon (volume)","tagline":"Trade it freely. The more of it changes hands, the closer its Entangled token gets to unlocking.","blurb":"No cap and no gate. The Beacon keeps an on-chain running total of how many of its tokens have changed hands: every buy, sell and wallet transfer adds to it, and it never goes down. Pair it with an Entangled token, and that token unlocks for good once the total reaches the amount you set.","family":"Reactive","venue":"verified","program":"5aAXdggDpJBtAfDoFusTp44tj5XpBXbxuCwDqpc17SBb","chips":[]},{"id":"combo","name":"Combined rules","tagline":"Several rules on one token, picked at launch.","blurb":"One hook that runs any mix of Trade guard, Anti-dump caps, Graduated sell caps, Max per wallet, Chapters, Rising max per wallet, Anti-bundle, DEX-only, FOMO-only buys and Sniper-fee cap. Each rule you pick works exactly like its single-rule version; the ones you don\'t pick are skipped. Pairs that would set the same limit twice can\'t be combined. Your wallet is exempt from the wallet caps, FOMO-only and the Sniper-fee cap. The rules are fixed at launch.","family":"Guards","venue":"safe","program":"C3vEdPepTPRrJdQ4nQ3ZmhdXCmpKdGRKVUqxduHZWbdR","chips":[]}]')},91845,e=>{"use strict";var t=e.i(45519);let a=new Set(["combo","skin","twoclass","dividends","royalty","realyield","entangled","beacon","oraclefloor","maxwallet","holdercap","basket","inverse","index","dumpcatcher","jackpot","halving","buyburn","tokendividends","milestonetreasury","abandonmentrefund","referral","diamondhand","gatedlaunch","progressivetax","p2ponly","dues","marketmon","rollingwaitlist","tieredmembership","vise","cooldown","convictioncap","whalegraduated"]),o=[{family:"Guards",title:"Guards & access",group:"hold"},{family:"Caps",title:"Caps & schedules",group:"sell"}],n=[{id:"pegs",group:"hold",name:"Pegs",demo:"pegs",desc:"The supply becomes a fixed collection of numbered objects, up to 65,535. Every whole unit a wallet holds is one of them, with its own number and art: buying across a unit mints a number, selling below one burns your newest, and sending tokens moves your newest objects with them. Upload your own art at launch, or let Hookvex draw one from each number.",chips:["numbered objects","your own art","moves with transfers"]},{id:"blocklist",group:"hold",name:"Blocklist",demo:"blocklist",desc:"The opposite of an allowlist: up to 200 wallets you name can never receive the token. They can't buy it and nobody can send it to them; everyone else trades normally, on any DEX. The list is sealed at launch, so it can never change.",chips:["named wallets can't receive","sealed at launch","trades on any DEX"]},{id:"allowlist",group:"hold",name:"Allowlist",demo:"list",desc:"You upload a list of wallets at launch. Only those wallets can receive the token, checked against a Merkle root with a proof carried in the trade.",chips:["your wallet list","Merkle-proof check","no presale contract"]},{id:"holdergated",group:"hold",name:"Holder-gated",demo:"gated",desc:"To receive this token a wallet must already hold a token you pick: a membership token, an NFT or another coin. The hook checks the receiving wallet's balance of it on every buy and transfer.",chips:["holders of your chosen token","checked on every transfer"]},{id:"vesting",group:"sell",name:"Holder vesting",demo:"vest",desc:"Each wallet's tokens unlock on their own clock from the moment it buys: nothing during the cliff, then a fixed share every period, from every hour to once a week. Vest every wallet, or only the ones that buy early, like a presale. A wallet can only sell what it has unlocked.",chips:["24h cliff","hourly to weekly","optional presale window"]},{id:"potato",group:"sell",name:"Hot potato",demo:"potato",desc:"Whoever bought last holds the hot potato: they can't sell or send until a different wallet buys after them, which passes it on. Everyone else trades freely and buys are never blocked. A buy has to reach your minimum to pass it, and you can let it go cold after a while. Nobody is exempt, you included.",chips:["last buyer is stuck","next buyer frees them","buys never blocked"]},{id:"antidump",group:"sell",name:"Anti-dump caps",demo:"antidump",desc:"The hook tells buys from sells and caps each side separately, so people can buy freely while no single trade can dump a big bag.",chips:["max buy 2% of supply","max sell 0.25% of supply"]},{id:"slidecap",group:"sell",name:"Sliding caps",demo:"antidump",desc:"The max per buy and max per sell change as the market cap grows. You set the caps at launch, then up to five market-cap levels where they change, for example max sell 1% at launch, 0.5% from $100,000 and 0.1% from $1,000,000, so whales have to exit in ever smaller pieces as the token grows. The hook reads the price from the token's own pool on every trade. If the market cap falls back under a level, the level below applies again. Nobody is exempt, including the creator.",chips:["max sell shrinks as it grows","up to 5 market-cap levels","caps as low as 0.001%"]},{id:"sellcaps",group:"sell",name:"Graduated sell caps",demo:"sellcap",desc:"Small holders sell freely, but the bigger a wallet's bag, the smaller its per-sell cap, down to a floor. A whale can build a position but can't dump it in one sell. Nothing to fund and no minimum buy: the hook reads the bag straight from the sell.",chips:["1% per sell for small bags","0.1% per sell at 3%+ bags","buys never capped"]},{id:"maxhold",group:"fair",name:"Max per wallet",demo:"walletcap",desc:"After every buy or transfer the hook checks what the receiving wallet now holds, and refuses the trade if it would go over your cap, for example 1% of supply. The Meteora pool and your own wallet are exempt. Nothing to fund and no per-wallet setup.",chips:["max 1% of supply per wallet","nothing to fund"]},{id:"chapters",group:"fair",name:"Chapters",demo:"chapters",desc:"A max per wallet that grows with the token. It starts small, for example 1% of supply, and doubles every time the total volume traded crosses another chapter, for example every 10,000,000 tokens. Selling back into the pool always works.",chips:["starts at 1% per wallet","doubles every 10M traded","selling always works"]},{id:"timecap",group:"fair",name:"Rising max per wallet",demo:"timecap",desc:"Every wallet's max holding starts small, for example 0.1% of supply, and rises for everyone on a timer you set: a fixed step or doubling. It never stops rising, so the token opens up completely over time. Snipers can only grab a tiny bag at launch. Nothing to fund and no per-wallet setup; the pool and your wallet are exempt.",chips:["starts at 0.1% per wallet","rises every 5 minutes","never stops rising"]},{id:"feecap",group:"fair",name:"Sniper-fee cap",demo:"feecap",desc:"Snipers win launches by outbidding everyone with huge priority fees and Jito tips. For a launch window you choose, the hook reads each buy's transaction and refuses it if it pays more than your cap. Normal buyers pay tiny fees and never notice. Sells are never blocked and your wallet is exempt.",chips:["max 0.002 SOL priority fee","max 0.002 SOL Jito tip","first 10 minutes"]},{id:"guard",group:"fair",name:"Trade guard",demo:"tradecap",desc:"Every buy, sell and transfer is capped at the same share of supply, for example 0.5%. Anything bigger is refused inside the swap, so no whale can grab or dump a big bag in one trade.",chips:["max 0.5% of supply per trade","buys and sells"]},{id:"antisniper",group:"fair",name:"Anti-bundle",demo:"bundle",desc:"The hook counts trades in each Solana block and refuses any past your limit. A bundler packing many buys into one block gets the first few at most, so nobody can buy up the launch in a single shot.",chips:["3 trades per block","bundles refused"]},{id:"venuelock",group:"trade",name:"Venue-locked",demo:"venue",desc:"Trades only through its Meteora pool. A plain wallet-to-wallet transfer is refused, so every trade hits your official liquidity and nobody can move the token quietly off-market between wallets.",chips:["pool trades only","no wallet-to-wallet moves"]},{id:"dexonly",group:"trade",name:"DEX-only",demo:"dex",desc:"Moves only when a program moves it, like a swap on the Meteora pool. A plain wallet-to-wallet send is refused, so the token can't be passed around off-market. Buying and selling through the pool work normally.",chips:["swaps only","no wallet-to-wallet sends"]},{id:"fomo",group:"trade",name:"FOMO-only buys",demo:"fomo",desc:"It can only be bought through the FOMO app. The hook checks that FOMO's own signing wallet co-signed each buy and refuses any buy that didn't come through FOMO. Launching includes a required dev buy. The dev wallet is also permanently whitelisted, so you can buy anywhere with it. Everyone else can only buy on FOMO. This lets the dev open up the pool on FOMO, which takes a few buys to trigger. Selling and sending always work, and the rule ends when the curve graduates.",chips:["buy on FOMO only","dev wallet whitelisted","sells never blocked"]},{id:"pumpapp",group:"trade",name:"Pump App only",demo:"pumpapp",desc:"It can only be bought in the Pump app. It can only be bought in the Pump app. The Pump app buys through Jupiter's app API and the OKX router, and the swap built for it carries a tag that jup.ag's own swaps don't; the hook refuses any buy without that tag on that router. Buying on jup.ag, in FOMO, through trading terminals like Axiom and Photon, or straight from the pool is refused. Another app built on the same Jupiter API could also get through. Launching includes a required dev buy, and the dev wallet is permanently whitelisted, so you can buy anywhere with it. Selling and sending always work, and the rule ends when the curve graduates.",chips:["buy in the Pump app only","jup.ag, FOMO and terminals refused","sells never blocked"]},{id:"social",group:"trade",name:"Social trading",demo:"social",desc:"It only trades in FOMO or the Pump app, buying and selling. A FOMO trade is recognised by FOMO's own signature. A Pump app trade is recognised by its route: it goes through Jupiter's app API and the OKX router, and carries a tag that jup.ag's own swaps don't. Trading on jup.ag, through terminals, or straight with the pool is refused both ways. Holders have no exit outside the two apps, so if both stop trading the token nobody can sell it. Launching includes a required dev buy, and the dev wallet is permanently whitelisted. Sending between wallets always works, and the rule ends when the curve graduates.",chips:["buy and sell in FOMO or the Pump app","jup.ag and terminals refused","no exit outside the two apps"]},{id:"opensea",group:"trade",name:"OpenSea only",demo:"opensea",desc:"It only trades on OpenSea, buying and selling. Every swap made on OpenSea carries OpenSea's own marker, and the hook refuses any trade without it, so there's no exit outside OpenSea. Launching includes a required dev buy, and the dev wallet is permanently whitelisted. Sending between wallets always works, and the rule ends when the curve graduates. OpenSea hasn't yet been seen trading a token still on its curve.",chips:["buy and sell on OpenSea only","dev wallet whitelisted","no exit outside OpenSea"]},{id:"pingpong",group:"when",name:"Ping Pong",demo:"pingpong",desc:"Buys and sells take turns: after a buy the next trade must be a sell, and after a sell it must be a buy, for everyone, the creator included. Trades under your minimum go through on their own turn but don't hand it over, and two trades in one transaction are refused, so nobody can game it with dust. If nobody takes the turn for a while, either side can go next. Sends always work, and the token page shows whose shot it is.",chips:["one buy, one sell","nobody exempt","token page shows the next shot"]},{id:"breathing",group:"physics",name:"Breathing cap",demo:"physics",desc:"An oscillator inside the hook swings the per-buy cap up and down on a fixed cycle, forever: wide open at the peaks, tight at the troughs. You choose the cycle, the base cap and the swing. Sells and sends are never capped, and your wallet is exempt.",chips:["cap breathes on the clock","forever, no crank","sells never capped"]},{id:"momentum",group:"physics",name:"Momentum",demo:"physics",desc:"A damped oscillator that starts at rest. Every buy kicks it and the cap swings up with it, so a run of buying opens room for bigger buys; then it swings back and settles when trading goes quiet. Sells and sends are never capped, and your wallet is exempt.",chips:["buying revs it up","rings down when quiet","sells never capped"]},{id:"resonance",group:"physics",name:"Resonance",demo:"physics",desc:"Momentum tuned for rhythm: buys that land in step with the natural period pile energy on and swing the cap far wider than scattered buys (5× the energy on devnet). A community buying on the beat unlocks the biggest buys. Sells and sends are never capped, and your wallet is exempt.",chips:["buy on the beat","rhythm beats volume","sells never capped"]},{id:"coupled",group:"physics",name:"Coupled resonator",demo:"physics",desc:"Two coupled oscillators in the hook. Buys energise the first, which sets the cap, and the coupling pours that energy into the second and back, so the cap swells and fades in beats. Sells and sends are never capped, and your wallet is exempt.",chips:["two oscillators","the cap beats","sells never capped"]},{id:"hours",group:"when",name:"Market hours",demo:"hours",desc:"Trades like a stock: only Monday to Friday, 9:30am to 4:00pm New York time. Outside the session the hook refuses the trade. You choose whether sells stay open around the clock and whether stock-market holidays are observed. Wallet-to-wallet sends always work. It can also be paired with a tokenized stock like NVDAx or TSLAx instead of SOL, so the token is priced in that stock.",chips:["Mon to Fri, 9:30am to 4pm ET","closed on market holidays","pair with SOL or 96 stocks"]},{id:"grudge",group:"hold",name:"The Grudge",demo:"list",desc:"For the wallets that farm a chart: buy, dump, buy back, dump again. The hook remembers every wallet that dumps a share of its bag you choose within 24 hours. For a time you set after each dump, that wallet pays an extra tax in SOL to buy, can't buy at all, or can only hold a little. The grudge can grow with every repeat. All of the tax goes to Hookvex's buyback and burn. Selling is never restricted, and it trades on any DEX.",chips:["remembers every dump","tax goes to buyback and burn","longer for repeat dumpers"]},{id:"redlight",group:"when",name:"Red light, Green light",demo:"hours",desc:"Trading runs on a traffic light that changes at random. On green, anyone can buy and sell. On red, every buy and every sell is refused by the token itself, for everyone, until it turns green again. Nobody knows when the next change is coming. The creator chooses how long each light lasts on average, and a red light never lasts more than three times its average. The token's page shows the light and every change. Sends between wallets are never paused, and it trades on any DEX.",chips:["green: trading open","red: trading paused","changes at random"]},{id:"options",group:"paid",name:"Options",demo:"list",desc:"Holders sell the right to buy their tokens at a set price. A holder offers some of their tokens at a price and until a date they choose, for a payment up front. If the token goes above that price, the buyer takes the tokens for less than they are worth; if not, the holder keeps the tokens and the payment. Listed tokens stay in the holder's wallet until someone buys, then they are set aside for the buyer. Offers fill whole or in pieces, are priced in SOL, and work with any pair.",chips:["earn from holding","buyers risk only the payment","works with any pair"]},{id:"polarity",group:"paid",name:"Polarity",demo:"list",desc:"Two tokens launched together, a BULL and a BEAR, tied to one price: SOL, Bitcoin, Ether, or any Hookvex token. Behind them is one pot of SOL, seeded by the creator and filled by about 1.6% of every trade on either token. When the price goes up, SOL moves from the bear side to the bull side, and the other way when it goes down, on every trade and at the leverage the creator picks. Holders redeem for 98% of their share of their side at any time; redeemed tokens are burned. Neither side's share can ever run out, and both trade on any DEX.",chips:["bull vs bear on one price","one pot of SOL, 1x to 5x","redeem your side any time"]},{id:"risingfloor",group:"paid",name:"Rising Floor",demo:"list",desc:"A price under the token that only goes up. About 1.6% of every trade goes into the token's own treasury, and the SOL in it is the floor: any holder can redeem tokens at any time for 98% of their share of it, with no buyer needed. Redeemed tokens are burned and the 2% left behind lifts the floor for everyone still holding. Nothing else can take SOL out, so the floor only rises. The token's rules add to it: wallets that dump pay a share of their next buys into the floor, and Block Zero Protection and a holding limit can be switched on with it. It trades on any DEX.",chips:["a floor that only rises","redeem any time, tokens burned","dumpers pay the floor"]},{id:"blockzero",group:"fair",name:"Block Zero Protection",demo:"bundle",desc:"The first block of a launch is where bundles happen: the dev buys and a string of side wallets buy in the same block. Here the first block belongs to the dev's wallet alone. The dev's launch buy opens trading, and every other buy in that block is refused by the token itself. From the next block on anyone can buy. The dev's wallet can never send its tokens to another wallet, so the launch bag can't be spread across side wallets; it can only sell, in plain view. Selling is never restricted, and it trades on any DEX.",chips:["only the dev buys in block zero","dev can't send tokens out","trades on any DEX"]},{id:"plague",group:"hold",name:"Plague",demo:"list",desc:"Nobody can simply buy it. A wallet can only buy once it already holds some, and the only way to get your first tokens is for a holder to send you some. It starts with the creator, who sends tokens to the first wallets; each of them can then buy and can infect anyone they like by sending tokens on. A wallet stays infected while it holds the token: sell or send away everything and it has to be sent some again. Selling is never restricted, and it trades on any DEX.",chips:["buy only after you're sent some","spreads wallet to wallet","trades on any DEX"]},{id:"custom",group:"custom",name:"Custom hook",demo:"custom",desc:"Your own rules, written with AI. Say what you want the token to do; the AI writes it as a short rule set, checks it with the real compiler and tests it, and you can edit every line. Rules can use the trade, each wallet's own buys and sells, the clock in any time zone, the market cap, fees and the app a trade came from. Stored on-chain at launch, fixed for good, and it still trades on any DEX.",chips:["describe it, AI writes it","tested before you launch","trades on any DEX"]},{id:"editable",group:"custom",name:"Editable hook",demo:"custom",desc:"A Custom hook that is never locked. Launch with any rules (or none) and rewrite them whenever you like with the same AI builder: only your wallet can make a change, each one is made on-chain, and the token's page always shows the rules as they are right now. 5% of the token's trading fees goes into its own fund that pays for the AI work; 80% still goes to the Hookvex buyback and burn. Normal 1% fee, and it trades on any DEX.",chips:["change the rules any time","only your wallet can","trades on any DEX"]},{id:"dao",group:"custom",name:"DAO hook",demo:"custom",desc:"A Custom hook run by its holders. Wallets holding the minimum you set post ideas for the rules and vote them up or down. When an idea reaches the votes you set, AI writes it as rules, tests it, and Hookvex's keeper puts it on-chain. Nobody can change the rules any other way, including you. 5% of the token's trading fees goes into its own fund that pays for the AI work and the changes; 80% still goes to the Hookvex buyback and burn. Normal 1% fee, and it trades on any DEX.",chips:["holders vote on the rules","AI writes what passes","trades on any DEX"]},{id:"hooki",group:"custom",name:"Hooki",demo:"custom",desc:"Hooki is an AI agent, and this token is his. He watches its buys, sells, volume, holders and market cap, and rewrites the token's rules whenever he decides to. Nobody tells him what to do and nobody else can change them, including the creator. The token's page shows what he is thinking, a countdown to his next look, and every change with his reason. He never locks holders in for good. 5% of the token's trading fees goes to his own wallet, which pays for his looks and his changes; above 2 SOL he may buy the token back and burn it as he sees fit; 80% still goes to the Hookvex buyback and burn. Normal 1% fee, and it trades on any DEX.",chips:["an AI agent runs the rules","fully autonomous","trades on any DEX"]},{id:"king",group:"paid",name:"King of the Hill",demo:"king",desc:"The largest qualifying buy holds the crown. Beat the King's winning buy in a single buy and you steal it; the bar slowly decays so the throne never becomes unreachable. While they hold the crown the King earns about 0.5% of every trade, paid in SOL by the program itself, and selling or sending any tokens gives it up. The token page shows the King, the reign and a Hall of Kings. Trades carry a 1.65% fee, and it trades on any DEX.",chips:["biggest buy takes the crown","the King earns from every trade","trades on any DEX"]},{id:"wars",group:"paid",name:"Social Trading Wars",demo:"social",desc:"FOMO against the Pump app, on one coin. It only trades in those two apps, like Social trading. Every wallet is on the side of the app it last bought through, and every hour the side with more holders wins that hour's war chest, about 1.6% of every trade, split between everyone on that side by how much they hold and paid in SOL. A tie rolls the chest over. Trades carry a 3% fee.",chips:["FOMO vs Pump","hourly winner takes the fees","paid in SOL"]},{id:"quantum",group:"paid",name:"Quantum Jackpot",demo:"conviction",desc:"Every round one holder wins the pot. About 1.6% of every trade goes into it, a round lasts 10 to 30 minutes, and the winner is drawn with a random number from quantum hardware that is published on-chain before the block that decides the draw. The more you hold the better your odds, and only tokens held since the last round count. Paid in SOL, and it trades on any DEX.",chips:["one winner every round","drawn by quantum hardware","paid in SOL"]},{id:"underwater",group:"paid",name:"Underwater",demo:"conviction",desc:"The fees go to the holders who are down. About 1.6% of every trade goes into a pot, and every five minutes it is shared between the holders whose tokens are worth less SOL than they paid for them, by how much each is down, and never more than that. A wallet is paid until it is back to even. The hook blocks nothing, so it trades anywhere. Trades carry a 3% fee.",chips:["pays holders who are down","every 5 minutes, in SOL","trades on any DEX"]},{id:"loans",group:"paid",name:"Loans, no liquidations",demo:"conviction",desc:"Holders pledge tokens and borrow SOL against them. Nothing is deposited: the pledged tokens stay in the holder's own wallet and the token itself refuses to sell or send them until they are released. Loans come from the token's own treasury, which fills with about 1% of every trade. There are no liquidations and no deadline: an unpaid loan just keeps its tokens frozen. Loans are sized from the SOL really in the pool, so nobody can borrow back more than they paid in. Pair it with a tokenized stock, a metal or another coin and holders borrow that instead. Trades carry a 2.25% fee (3% when paired), and it trades on any DEX.",chips:["collateral never leaves the wallet","no liquidations, ever","trades on any DEX"]},{id:"lockin",group:"paid",name:"Lock & earn",demo:"conviction",desc:"Holders lock tokens for a length of time and earn SOL from every trade. Nothing is deposited: the tokens stay in the holder's own wallet and the token itself refuses to sell or send them until the lock ends. About 1% of every trade is paid in SOL to the wallets with locks, by how much they locked and for how long. Comes with ready-made setups (lock to earn, long-term boost, loyalty tiers, one fixed lock) or set every number yourself, and you can lock your own launch buy for everyone to see. Trades carry a 2.25% fee, and it trades on any DEX.",chips:["locks never leave the wallet","lockers earn SOL from every trade","trades on any DEX"]},{id:"arcade",group:"fair",name:"Arcade",demo:"conviction",desc:"The token comes with a game. Anyone can hold up to 0.1% of the supply; reach the score its creator set and your wallet can hold any amount, for good. Playing is free, every run is replayed on-chain with the game's own logic so a score can't be faked, and your best score is kept forever. Sends are capped like buys, selling is never touched, and it trades on any DEX.",chips:["beat the game to hold more","scores checked on-chain","free to play"]},{id:"iqtest",group:"fair",name:"IQ test",demo:"conviction",desc:"The token comes with a 20-question IQ test, made fresh for every run. Anyone can hold up to 0.1% of the supply; score the IQ its creator set and your wallet can hold any amount, for good. Easy, normal or hard, a minute per question, retakes any time, and every run is checked on-chain. Sends are capped like buys, selling is never touched, and it trades on any DEX.",chips:["pass the IQ test to hold more","checked on-chain","retake any time"]},{id:"conviction",group:"fair",name:"Conviction cap",demo:"conviction",desc:"Every wallet starts with a small limit per buy. Each minute, hour or day it holds without selling (you choose), its own limit climbs, up to a ceiling you set; sell and that wallet's clock starts again. New money is throttled while proven holders can buy bigger. Sells are never capped, your wallet is exempt, and it trades on any DEX.",chips:["buy cap grows as you hold","selling resets it","trades on any DEX"]},{id:"schedule",group:"when",name:"Trading hours",demo:"schedule",desc:"You set the trading week: which days it trades and the hours on each, in any time zone in the world, with daylight saving followed on-chain. Outside those hours the hook refuses the trade. A day can run past midnight or stay open all day, and you choose whether sells stay open around the clock. Wallet-to-wallet sends always work.",chips:["your days, your hours","any time zone","daylight saving handled"]},{id:"p2p",group:"trade",name:"P2P-only",demo:"p2p",desc:"The opposite of Venue-locked: it moves only wallet to wallet, and nobody can buy or sell it on a market. Only you can buy from the bonding curve, even all of it, and hand tokens out. When the curve fills up it graduates, the rule switches off, and it trades normally.",chips:["wallet to wallet only","you can buy the curve","rule ends at graduation"]},{id:"airdrop",group:"paid",name:"Buyer rewards",demo:"airdrop",desc:"Fill a vault with any token or with NFTs. Every qualifying buy earns the buyer a reward, which they collect on Hookvex, even if they've never held that token. Buys only earn while the vault can cover them. You can withdraw anything not already owed to buyers.",chips:["tokens or NFTs","buyers collect on Hookvex","withdraw what isn't owed"]},{id:"tithe",group:"paid",name:"Tithe",demo:"tithe",desc:"The same enforcement as a royalty, but the payment goes to a cause you name: a charity, a treasury, a public-goods fund.",chips:["0.005 SOL per trade","to an address you pick"]},{id:"reactive",group:"link",name:"Reactive pair",demo:"reactive",desc:"Two tokens that watch each other. Each one's per-buy cap loosens while the other is being bought and tightens while it's being sold, so momentum in one opens the door in the other. Sells are never capped. Launch the two together.",chips:["cap moves with its partner","sells never capped","launch as a pair"]},{id:"capentangled",group:"link",name:"Entangled",demo:"entangled",desc:"Stays locked until its Beacon token's market cap reaches the target you set, for example $20,000. Then it unlocks for good, even if the Beacon falls back later. Launch the two as a pair.",chips:["unlocks at a market cap","permanent unlock","launch as a pair"]},{id:"capbeacon",group:"link",name:"Beacon",demo:"beacon",desc:"Trades freely with no cap. Its hook remembers the highest market cap it has reached, and hitting the target is what unlocks its Entangled partner.",chips:["no cap","tracks its market cap"]}],s=n.map(e=>{let a,o=(a=e.id,t.default.find(e=>e.id===a)),n="polarity"===e.id||"risingfloor"===e.id||"underwater"===e.id||"quantum"===e.id||"loans"===e.id||"wars"===e.id||"lockin"===e.id||"airdrop"===e.id||"pumpapp"===e.id||"timecap"===e.id||"feecap"===e.id||"hours"===e.id||"slidecap"===e.id||"social"===e.id||"opensea"===e.id||"pingpong"===e.id||"breathing"===e.id||"momentum"===e.id||"resonance"===e.id||"coupled"===e.id||"pegs"===e.id||"potato"===e.id||"blocklist"===e.id||"schedule"===e.id||"custom"===e.id||"arcade"===e.id||"iqtest"===e.id||"conviction"===e.id||"king"===e.id||"editable"===e.id||"dao"===e.id||"hooki"===e.id||"plague"===e.id||"grudge"===e.id||"blockzero"===e.id||"options"===e.id||"redlight"===e.id;return{...e,anyVenue:"client"!==o.venue,verified:!n,fresh:n,family:o.family,program:o.program}}),r=t.default.filter(e=>!n.some(t=>t.id===e.id)&&!a.has(e.id)).map(e=>{let t=e.family;return{id:e.id,name:e.name,group:o.find(e=>e.family===t)?.group??"link",demo:"Rewards"===t||"Emission"===t?"reward":"gate",anyVenue:"client"!==e.venue,desc:e.blurb,chips:e.chips,verified:!1,fresh:!1,family:t,program:e.program}}),i=[...s,...o.flatMap(e=>r.filter(t=>t.family===e.family))];e.s(["GROUPS",0,[{id:"custom",title:"AI-assisted hook creation"},{id:"hold",title:"Who can hold"},{id:"sell",title:"When you can sell"},{id:"fair",title:"Fair launch"},{id:"trade",title:"Where it trades"},{id:"when",title:"When it trades"},{id:"physics",title:"Physics in tokens"},{id:"paid",title:"Who gets paid"},{id:"link",title:"Linked tokens"}],"GROUP_COLOR",0,{custom:"#F4EEFF",hold:"#3BE3FF",sell:"#9D5CFF",fair:"#FFD23F",trade:"#7AA2FF",when:"#43F0A0",physics:"#C6FF4D",paid:"#FF8A3D",link:"#FF2E93"},"LAB_FAMILIES",0,o,"LAB_RULES",0,r,"RULES",0,i,"VERIFIED_RULES",0,s,"ruleById",0,e=>i.find(t=>t.id===e)])}]);